"""Outside-runner v2 records from observed producer metadata, not recreated history."""
import hashlib,json,pathlib,platform
P=pathlib.Path(__file__).resolve().parent;ROOT=P.parents[1];dest=P/'run_manifests';dest.mkdir(exist_ok=True)
for pat in ['late_runs/*.json','binding_runs/*.json','binding_phase_runs/*.json','radial_runs/*.json','assembly_screen.json']:
 for f in sorted(P.glob(pat)):
  d=json.loads(f.read_text());outs=[q for q in [f,f.with_suffix('.npz'),f.with_suffix('.stdout')] if q.exists()];outputs=[dict(path=str(q.relative_to(ROOT)),sha256=hashlib.sha256(q.read_bytes()).hexdigest(),kind='result') for q in outs]
  rec=dict(schema_version=2,claim_id='CCT017_'+f.parent.name+'_'+f.stem,repository=dict(commit=d['revision_before'],dirty=True),command=[d['interpreter']]+d['argv'],environment=dict(software=[dict(name=k,version=v) for k,v in d['software'].items()],hardware=platform.machine()+' '+platform.system()),mathematics=dict(assertion_tested='Finite conditional wave evolution, snapshot/window energetic bound, or initial-energy quadratic screen as declared in producer scope',coefficient_domain='float64/complex128',conventions=d['scope'],inputs=['saved initial CCT field or explicit saved complex conditional checkpoint'],bounds=d['parameters'],non_claims=['no continuum escape or settled bound remnant','no four-dwarf or evolved-star closure','no current-action bridge']),randomness=dict(used=False,generator='',seed=None),run=dict(started_at=d['started_utc'],runtime_seconds=d['seconds'],exit_status=0,status='completed',resource_limits=dict(memory_bytes=None,cpu_seconds=None,max_cores=None,max_threads=None)),outputs=outputs,checks=[dict(name='input pins unchanged',passed=d['inputs_before']==d['inputs_after'])],result=d['status'],residual_risks=['completed means process completed; result retains physical/resource stop','Measured RSS '+str(d['peak_RSS_bytes'])+' bytes; no hard allocation cap','One-thread environment request, no enforced affinity','Soft wall checkpoint and measured memory gates','Producer runtime/RSS may exclude final serialization','Global invariants do not validate local currents; require shell and grid/time comparisons','Revision after '+d['revision_after']+'; exact hashes identify sources under concurrent owner commits'],input_artifacts=[dict(path=k,sha256=v,sha256_after=d['inputs_after'][k]) for k,v in d['inputs_before'].items()],declared_results=[o['path'] for o in outputs])
  (dest/(f.parent.name+'_'+f.stem+'.json')).write_text(json.dumps(rec,indent=2)+'\n')
print(len(list(dest.glob('*.json'))),'outside-runner records')
